        }
      } else {
        // Rejection sampling accepts `alphabetLen` of every `mask + 1`
        // random bytes. `1.6` requests extra bytes to cover
        // unlucky streaks in most fills.
        let randomBytes = Buffer.allocUnsafe(
          Math.ceil((1.6 * (mask + 1) * target) / alphabetLen)
        )
        let accepted = 0
        while (accepted < target) {
          fillRandom(randomBytes)
          for (let i = 0; i < randomBytes.length; i++) {
            let index = randomBytes[i] & mask
            if (index < alphabetLen) {
              buffer[accepted++] = charCodes[index]
              if (accepted === target) break
            }
          }
        }
      }
      pool = buffer.toString('latin1')
      poolOffset = 0
    }
    poolOffset += size
    return pool.substring(poolOffset - size, poolOffset)
  }
}

### Custom Random Bytes Generator

`customRandom` allows you to create a `nanoid` and replace alphabet
and the default random bytes generator.

In this example, a seed-based generator is used:

```js
import { customRandom } from "nanoid";

const rng = seedrandom(seed);
const nanoid = customRandom("abcdef", 10, (size) => {
  return new Uint8Array(size).map(() => 256 * rng());
});

nanoid(); //=> "fbaefaadeb"
```

`random` callback must accept the array size and return an array
with random numbers.

If you want to use the same URL-friendly symbols with `customRandom`,
you can get the default alphabet using the `urlAlphabet`.

```js
import { customRandom, urlAlphabet } from "nanoid";
const nanoid = customRandom(urlAlphabet, 10, random);
```

Note, that between Nano ID versions we may change random generator
call sequence. If you are using seed-based generators, we do not guarantee
the same result.

